import React from 'react';
import { Layout, Collapse } from 'antd';
import { usePhotoEditor } from '../context';
import Toolbar from './Toolbar';
import CanvasArea from './CanvasArea';
import LayersPanel from './LayersPanel';
import PropertiesPanel from './PropertiesPanel';
import HistoryPanel from './HistoryPanel';
import PhotoEditorErrorBoundary from './PhotoEditorErrorBoundary';

const { Sider, Content } = Layout;
const { Panel } = Collapse;

const EditorLayout: React.FC = () => {
  const { history, isBusy } = usePhotoEditor();

  return (
    <PhotoEditorErrorBoundary>
      <Layout className="peEditorLayout" aria-busy={isBusy} style={{ height: '100%', pointerEvents: isBusy ? 'none' : undefined, opacity: isBusy ? 0.7 : 1 }}>
        <Sider theme="light" width={60} className="peToolbarSider">
          <Toolbar />
        </Sider>
        <Content className="peCanvasContent">
          <CanvasArea />
        </Content>
        <Sider theme="light" width={300} className="pePropertiesSider">
          <PropertiesPanel />
          <Collapse
            defaultActiveKey={['layers']}
            bordered={false}
            className="pePanelCollapse"
            style={{ background: 'transparent' }}
          >
            <Panel header="Layers" key="layers" style={{ padding: 0 }}>
              <LayersPanel />
            </Panel>
            <Panel header="History" key="history" style={{ padding: 0 }}>
              <div style={{ overflow: 'hidden' }}>
                <HistoryPanel
                  entries={history.entries}
                  currentIndex={history.currentIndex}
                  onGoToEntry={history.goToEntry}
                  onUndo={history.undo}
                  onRedo={history.redo}
                  canUndo={history.canUndo}
                  canRedo={history.canRedo}
                  isProcessing={history.isProcessing}
                />
              </div>
            </Panel>
          </Collapse>
        </Sider>
      </Layout>
    </PhotoEditorErrorBoundary>
  );
};

export default EditorLayout;
